ntity, sale_order_number, sales, total from snitch_db.MAPLEMONK.MIS_20260428 ), cost_price_map as ( select sku_group, cost_price, category from SNITCH_DB.MAPLEMONK.base_product qualify row_number() over ( partition by sku_group order by cost_price desc ) = 1 ), cat_mp as ( select case when left(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)), \'-\', 0) else UPPER(TRIM(SKUGROUP)) end as sku_group, case when category = \'Jacket\' then \'Jackets\' when category = \'Jacket\' then \'Jackets\' when category in ( \'PYJAMAS\', \'Night Suit & Pyjamas\', \'Joggers & Trackpants\', \'Trackpants\', \'JOGGERS\' ) then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\', \'Chinos\') then \'Trousers\' else category end as category from snitch_db.maplemonk.uc_final_item_master qualify row_number() over ( partition by case when left(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)), \'-\', 0) else UPPER(TRIM(SKUGROUP)) end order by case when category = \'Jacket\' then \'Jackets\' when category = \'Jacket\' then \'Jackets\' when category in ( \'PYJAMAS\', \'Night Suit & Pyjamas\', \'Joggers & Trackpants\', \'Trackpants\', \'JOGGERS\' ) then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\', \'Chinos\') then \'Trousers\' else category end asc ) = 1 ), shopify_gross as ( select original_invoice_date as date, sale_order_number as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, \'Shopify\' as Channel, sum(quantity)::int as quantity, sum(sales)::int as sales, sum((mrp * quantity))::int as mrp, sum(total)::int as total, sum( coalesce( try_to_number( nullif( regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\' ) ), 0 ) * coalesce( try_to_number( nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\') ), 0 ) )::int as cost_price from main where channel_ledger = \'Snitch\' and entity = \'NEW_INVOICE\' group by 1, 2, 3, 4 ), shopify_net as ( select \"Display Order Number\" as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\") ) ) ) ) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where \"Channel Ledger\" = \'Snitch\' group by 1, 2 ), shopify as ( select a.*, case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end as return_qty, case when ifnull(b.return_qty, 0) > quantity then \'false\' else \'true\' end as flag, sales * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_sales, mrp * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_mrp, total * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_total, cost_price * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_cost_price from shopify_gross a left join shopify_net b on a.order_name = b.order_name and a.sku_group = b.sku_group ), shopify_main as ( select a.date, a.sku_group, b.category, a.Channel, sum(quantity) as quantity, sum(quantity - return_qty) as net_quantity, sum(total) as sales, sum(net_total) as net_sales, sum(mrp - total) as discount, sum(net_mrp - net_total) as net_discount, sum(a.cost_price) as cost_price, sum(net_cost_price) as net_cost_price from shopify a left join cost_price_map b on a.sku_group = b.sku_group group by 1, 2, 3, 4 ), mp_gross as ( select original_invoice_date as date, sale_order_number as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, case when channel_ledger in ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\' ) then \'MP_Ajio\' when channel_ledger in (\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\') then \'MP_Amazon\' when channel_ledger in ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) then \'MP_Myntra_PPMP\' when channel_ledger in ( \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) then \'MP_Nykaa\' else \'others\' end as Channel, sum(quantity) as quantity, sum( case when channel_ledger in ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) then total when channel_ledger in ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) and original_invoice_date >= \'2026-03-26\' then total + quantity * avg_cat_charges when channel_ledger in ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) then total when channel_ledger in ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\' ) then (total / 0.68)::INT ELSE SALES END )::int AS SALES, sum( coalesce( try_to_number(nullif(regexp_replace(MRP, \'[^0-9.-]\', \'\'), \'\')), 0 ) * coalesce( try_to_number( nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\') ), 0 ) ) as MRP, sum( coalesce( try_to_number( nullif( regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\' ) ), 0 ) * coalesce( try_to_number( nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\') ), 0 ) ) as cp from main a left join cost_price_map b on trim( upper( REVERSE( SUBSTRING( REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code) ) ) ) ) = b.sku_group left join snitch_db.maplemonk.AVG_GT_CHARGES c on b.category = c.category where channel_ledger in ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) group by 1, 2, 3, 4 ), mp_return as ( select \"Display Order Number\" as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\") ) ) ) ) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where \"Channel Ledger\" in ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) group by 1, 2 ), mp_main_pre as ( select a.*, case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end as return_qty, case when ifnull(b.return_qty, 0) > quantity then \'false\' else \'true\' end as flag, sales * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_sales, mrp * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_mrp, cp * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_cp from mp_gross a left join mp_return b on a.order_name = b.order_name and a.sku_group = b.sku_group ), mp_main as ( select a.date, a.sku_group, b.category, a.Channel, sum(quantity) as quantity, sum(quantity - return_qty) as net_quantity, sum(sales) as sales, sum(net_sales) as net_sales, sum(mrp - sales) as discount, sum(net_mrp - net_sales) as net_discount, sum(cp) as cost_price, sum(net_cp) as net_cost_price from mp_main_pre a left join cost_price_map b on a.sku_group = b.sku_group group by 1, 2, 3, 4 ), offline_pre as ( select b.order_date::date as date, coalesce(cp.category, \'others\') as category, \'Store\' as channel, b.sku_group, case when marketplace_mapped in ( \'SNITCH - WH - B2B\', \'SNITCH - SNITCH X\', \'SNITCH - WH - M P\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - U.P\', \'SNITCH - WH - NORTH\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - EMIZA\', \'SNITCH - WH - YELHANKA 2\' ) or b.sku_group like \'cb%\' or doc_prefix in (\'OMS\', \'QCOM\') then 1 else 0 end as filters, sum(b.shipping_quantity)::int as quantity, sum(b.shipping_quantity)::int as net_quantity, sum(b.selling_price)::int as sales, sum(b.selling_price)::int as net_sales, sum(discount)::int as discount, sum(discount)::int as net_discount, (sum(cp.cost_price * b.shipping_quantity))::int as cost_price, (sum(cp.cost_price * b.shipping_quantity))::int as net_cost_price, from snitch_db.maplemonk.store_fact_items_offline b left join cost_price_map cp on b.sku_group = cp.sku_group where coalesce(cp.category, \'others\') <> \'others\' group by 1, 2, 3, 4, 5 ), offline_main as ( select date, sku_group, category, channel, quantity, net_quantity, sales, net_sales, discount, net_discount, cost_price, net_cost_price from offline_pre where filters = 0 ), myntra_sor as ( select TO_DATE(order_created_date, \'YYYYMMDD\') AS date, upper(trim(a.style)) sku_group, b.category, \'MP_myntra_SOR\' as channel, sum(sales) as quantity, sum(sales) as net_quantity, sum(replace(revenue, \',\', \'\')) as sales, sum(replace(revenue, \',\', \'\')) as net_sales, sum( replace(\"MRP Sales\", \',\', \'\') - replace(revenue, \',\', \'\') ) as discount, sum( replace(\"MRP Sales\", \',\', \'\') - replace(revenue, \',\', \'\') ) as net_discount, sum(replace(cogs_qty, \',\', \'\')) as cost_price, sum(replace(cogs_qty, \',\', \'\')) as net_cost_price from snitch_db.maplemonk.S3_MYNTRA_B2B_GP a left join cat_mp b on upper(trim(a.style)) = b.sku_group group by 1, 2, 3, 4 ), flipkart_sor as ( select TO_DATE(order_date_key, \'YYYYMMDD\') AS date, upper(trim(a.style)) sku_group, category, \'MP_flipkart_SOR\' as channel, sum(replace(units, \',\', \'\')) as quantity, sum(replace(units, \',\', \'\')) as net_quantity, sum(replace(SP_Qty, \',\', \'\')) as sales, sum(replace(SP_Qty, \',\', \'\')) as net_sales, sum( replace(\"MRP Rev\", \',\', \'\') - replace(SP_QTY_EXCL_GST, \',\', \'\') ) as discount, sum( replace(\"MRP Rev\", \',\', \'\') - replace(SP_QTY_EXCL_GST, \',\', \'\') ) as net_discount, sum(replace(COGS_UNITS, \',\', \'\')) as cost_price, sum(replace(COGS_UNITS, \',\', \'\')) as net_cost_price from snitch_db.maplemonk.S3_Flipkart_B2B_GP a left join cat_mp b on upper(trim(a.STYLE)) = b.sku_group group by 1, 2, 3, 4 ), slikk as ( select TO_DATE(order_date, \'DD-MM-YYYY\') AS date, upper(trim(a.\"Style \")) sku_group, category, \'MP_slikk\' as channel, sum(total_quantity) as quantity, sum(total_quantity) as net_quantity, sum(total_amount) as sales, sum(total_amount) as net_sales, sum((mrp * total_quantity) - total_amount) as discount, sum((mrp * total_quantity) - total_amount) as net_discount, sum(\"COGSxQty \") as cost_price, sum(\"COGSxQty \") as net_cost_price from snitch_db.maplemonk.google_sheets_slikk a left join cat_mp b on upper(trim(a.\"Style \")) = b.sku_group group by 1, 2, 3, 4 ), base as ( select * from shopify_main union all select * from offline_main union all select * from mp_main union all select * from myntra_sor union all select * from flipkart_sor union all select * from slikk ),live_date_map as ( select sku_group, min(date) as live_date, from base where date is not null and quantity > 0 group by 1 ), base_filtered as ( select b.* from base b join params p on 1 = 1 where b.date <= p.as_of_date ), l30d_sales as ( select b.sku_group, sum(b.quantity)::number as l30d_qty_gross, sum(b.net_quantity)::number as l30d_qty_net from base b join params p on 1 = 1 where b.date > dateadd(day, -30, p.as_of_date) and b.date <= p.as_of_date group by 1 ), daily as ( select category, sku_group, sum(quantity)::number as quantity, sum(sales)::number as sales, sum(discount)::number as discount, sum(cost_price)::number as cost_price, sum(net_quantity)::number as net_quantity, sum(net_sales)::number as net_sales, sum(net_discount)::number as net_discount, sum(net_cost_price)::number as net_cost_price from base_filtered group by 1, 2 ), daily_final as ( select d.category, d.sku_group, d.sales, d.quantity, d.discount, d.cost_price, d.net_sales, d.net_quantity, d.net_discount, d.net_cost_price, from daily d ), img as ( WITH images AS ( SELECT UPPER( TRIM( CASE WHEN variant.value:sku::STRING ILIKE \'4C%\' OR variant.value:sku::STRING ILIKE \'MP%\' THEN REGEXP_SUBSTR(variant.value:sku::STRING, \'^[^-]+-[^-]+-[^-]+\') ELSE REGEXP_SUBSTR(variant.value:sku::STRING, \'^[^-]+-[^-]+\') END ) ) AS sku_group, image.value:preview:image:url::STRING AS image_url, image.index AS image_index FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => PARSE_JSON(t.media)) AS image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant WHERE image.value:mediaContentType::STRING = \'IMAGE\' ) SELECT sku_group, image_url FROM images QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY image_index ) = 1 ), inv as ( select * from snitch_db.maplemonk.inv_logs where date = ( select max(date) -1 from snitch_db.maplemonk.inv_logs ) ) select df.*, img.image_url, coalesce(total_qty, 0) inv, ld.live_date, case when ld.live_date is null then null else datediff( day, ld.live_date, ( select as_of_date from params ) ) end as days_since_live, coalesce(l30.l30d_qty_gross, 0) as l30d_qty_gross, coalesce(l30.l30d_qty_net, 0) as l30d_qty_net from daily_final df left join img using(sku_group) left join inv using(sku_group) left join live_date_map ld using(sku_group) left join l30d_sales l30 using(sku_group) where sku_group in ( \'4RN216-01\', \'4RN217-01\', \'4RN218-01\', \'4RN219-01\', \'4RN224-01\', \'4RN222-01\', \'4RN224-02\', \'4PL122-01\', \'4PL122-02\', \'4PL124-01\', \'4PL124-02\', \'4PL127-01\', \'4TR034-01\', \'4TR034-02\', \'4TR035-01\', \'4TR035-02\', \'4RN221-01\', \'4PL123-01\', \'4PL125-01\', \'4OS019-01\', \'4OS019-02\', \'4JE093-01\', \'4JE093-02\', \'4SH018-01\', \'4JO007-01\', \'4CA004-01\', \'4OS020-01\', \'4RN223-01\', \'4RN223-02\', \'4RN223-03\', \'4SHS151-01\', \'4SHS151-02\', \'4RN220-01\', \'4SHS144-01\', \'4PL126-01\', \'4SFS150-01\', \'4SFS150-02\', \'4SHS143-01\', \'4SHS145-01\', \'4SHS147-01\', \'4SHS147-02\', \'4SHS148-01\', \'4SHS149-01\', \'4SHS175-01\' );",
